const channelSelect = h("select", {style:"display:none;max-width:100%"});
const channelHint = h("div", {class:"muted",style:"display:none"});
const refreshChannels = h("button", {class:"sec",textContent:"Muat ulang saluran",style:"display:none"});
function updateChannels() {
  const show = destSel.value === "channel";
  channelSelect.style.display = channelHint.style.display = refreshChannels.style.display = show ? "" : "none";
  if (!show) return;
  const prev = channelSelect.value;
  channelSelect.replaceChildren(h("option",{value:"",textContent:"Pilih saluran admin/owner"}));
  try {
    for (const ch of WAAS.wa.listChannels()) channelSelect.append(h("option",{value:ch.id,textContent:ch.name+" ("+ch.role+")"}));
    if (Array.from(channelSelect.options).some(o=>o.value===prev)) channelSelect.value=prev;
    const d=WAAS.wa.channelDiagnostics();
    channelHint.textContent = "Fitur saluran: "+String(d.enabled)+" · saluran admin/owner: "+String(d.writableChannels)+". Pengiriman audio masih eksperimental.";
  } catch(e) {channelHint.textContent=e.message;}
}
destSel.addEventListener("change",updateChannels);
refreshChannels.addEventListener("click",updateChannels);
